"""Original PaperCoder prompts with explicit dependencies and no inference code."""

def planning_messages(paper_content: str, paper_format: str) -> list[list[dict[str, str]]]:
    """Build the four original planning instruction groups."""
    plan_msg = [{'role': 'system', 'content': f"You are an expert researcher and strategic planner with a deep understanding of experimental design and reproducibility in scientific research. \nYou will receive a research paper in {paper_format} format. \nYour task is to create a detailed and efficient plan to reproduce the experiments and methodologies described in the paper.\nThis plan should align precisely with the paper's methodology, experimental setup, and evaluation metrics. \n\nInstructions:\n\n1. Align with the Paper: Your plan must strictly follow the methods, datasets, model configurations, hyperparameters, and experimental setups described in the paper.\n2. Be Clear and Structured: Present the plan in a well-organized and easy-to-follow format, breaking it down into actionable steps.\n3. Prioritize Efficiency: Optimize the plan for clarity and practical implementation while ensuring fidelity to the original experiments."}, {'role': 'user', 'content': f"## Paper\n{paper_content}\n\n## Task\n1. We want to reproduce the method described in the attached paper. \n2. The authors did not release any official code, so we have to plan our own implementation.\n3. Before writing any Python code, please outline a comprehensive plan that covers:\n   - Key details from the paper's **Methodology**.\n   - Important aspects of **Experiments**, including dataset requirements, experimental settings, hyperparameters, or evaluation metrics.\n4. The plan should be as **detailed and informative** as possible to help us write the final code later.\n\n## Requirements\n- You don't need to provide the actual code yet; focus on a **thorough, clear strategy**.\n- If something is unclear from the paper, mention it explicitly.\n\n## Instruction\nThe response should give us a strong roadmap, making it easier to write the code later."}]
    file_list_msg = [{'role': 'user', 'content': 'Your goal is to create a concise, usable, and complete software system design for reproducing the paper\'s method. Use appropriate open-source libraries and keep the overall architecture simple.\n             \nBased on the plan for reproducing the paper’s main method, please design a concise, usable, and complete software system. \nKeep the architecture simple and make effective use of open-source libraries.\n\n-----\n\n## Format Example\n[CONTENT]\n{\n    "Implementation approach": "We will ... ,\n    "File list": [\n        "main.py",  \n        "dataset_loader.py", \n        "model.py",  \n        "trainer.py",\n        "evaluation.py" \n    ],\n    "Data structures and interfaces": "\nclassDiagram\n    class Main {\n        +__init__()\n        +run_experiment()\n    }\n    class DatasetLoader {\n        +__init__(config: dict)\n        +load_data() -> Any\n    }\n    class Model {\n        +__init__(params: dict)\n        +forward(x: Tensor) -> Tensor\n    }\n    class Trainer {\n        +__init__(model: Model, data: Any)\n        +train() -> None\n    }\n    class Evaluation {\n        +__init__(model: Model, data: Any)\n        +evaluate() -> dict\n    }\n    Main --> DatasetLoader\n    Main --> Trainer\n    Main --> Evaluation\n    Trainer --> Model\n",\n    "Program call flow": "\nsequenceDiagram\n    participant M as Main\n    participant DL as DatasetLoader\n    participant MD as Model\n    participant TR as Trainer\n    participant EV as Evaluation\n    M->>DL: load_data()\n    DL-->>M: return dataset\n    M->>MD: initialize model()\n    M->>TR: train(model, dataset)\n    TR->>MD: forward(x)\n    MD-->>TR: predictions\n    TR-->>M: training complete\n    M->>EV: evaluate(model, dataset)\n    EV->>MD: forward(x)\n    MD-->>EV: predictions\n    EV-->>M: metrics\n",\n    "Anything UNCLEAR": "Need clarification on the exact dataset format and any specialized hyperparameters."\n}\n[/CONTENT]\n\n## Nodes: "<node>: <type>  # <instruction>"\n- Implementation approach: <class \'str\'>  # Summarize the chosen solution strategy.\n- File list: typing.List[str]  # Only need relative paths. ALWAYS write a main.py or app.py here.\n- Data structures and interfaces: typing.Optional[str]  # Use mermaid classDiagram code syntax, including classes, method(__init__ etc.) and functions with type annotations, CLEARLY MARK the RELATIONSHIPS between classes, and comply with PEP8 standards. The data structures SHOULD BE VERY DETAILED and the API should be comprehensive with a complete design.\n- Program call flow: typing.Optional[str] # Use sequenceDiagram code syntax, COMPLETE and VERY DETAILED, using CLASSES AND API DEFINED ABOVE accurately, covering the CRUD AND INIT of each object, SYNTAX MUST BE CORRECT.\n- Anything UNCLEAR: <class \'str\'>  # Mention ambiguities and ask for clarifications.\n\n## Constraint\nFormat: output wrapped inside [CONTENT][/CONTENT] like the format example, nothing else.\n\n## Action\nFollow the instructions for the nodes, generate the output, and ensure it follows the format example.'}]
    task_list_msg = [{'role': 'user', 'content': 'Your goal is break down tasks according to PRD/technical design, generate a task list, and analyze task dependencies. \nYou will break down tasks, analyze dependencies.\n             \nYou outline a clear PRD/technical design for reproducing the paper’s method and experiments. \n\nNow, let\'s break down tasks according to PRD/technical design, generate a task list, and analyze task dependencies.\nThe Logic Analysis should not only consider the dependencies between files but also provide detailed descriptions to assist in writing the code needed to reproduce the paper.\n\n-----\n\n## Format Example\n[CONTENT]\n{\n    "Required packages": [\n        "numpy==1.21.0",\n        "torch==1.9.0"  \n    ],\n    "Required Other language third-party packages": [\n        "No third-party dependencies required"\n    ],\n    "Logic Analysis": [\n        [\n            "data_preprocessing.py",\n            "DataPreprocessing class ........"\n        ],\n        [\n            "trainer.py",\n            "Trainer ....... "\n        ],\n        [\n            "dataset_loader.py",\n            "Handles loading and ........"\n        ],\n        [\n            "model.py",\n            "Defines the model ......."\n        ],\n        [\n            "evaluation.py",\n            "Evaluation class ........ "\n        ],\n        [\n            "main.py",\n            "Entry point  ......."\n        ]\n    ],\n    "Task list": [\n        "dataset_loader.py", \n        "model.py",  \n        "trainer.py", \n        "evaluation.py",\n        "main.py"  \n    ],\n    "Full API spec": "openapi: 3.0.0 ...",\n    "Shared Knowledge": "Both data_preprocessing.py and trainer.py share ........",\n    "Anything UNCLEAR": "Clarification needed on recommended hardware configuration for large-scale experiments."\n}\n\n[/CONTENT]\n\n## Nodes: "<node>: <type>  # <instruction>"\n- Required packages: typing.Optional[typing.List[str]]  # Provide required third-party packages in requirements.txt format.(e.g., \'numpy==1.21.0\').\n- Required Other language third-party packages: typing.List[str]  # List down packages required for non-Python languages. If none, specify "No third-party dependencies required".\n- Logic Analysis: typing.List[typing.List[str]]  # Provide a list of files with the classes/methods/functions to be implemented, including dependency analysis and imports. Include as much detailed description as possible.\n- Task list: typing.List[str]  # Break down the tasks into a list of filenames, prioritized based on dependency order. The task list must include the previously generated file list.\n- Full API spec: <class \'str\'>  # Describe all APIs using OpenAPI 3.0 spec that may be used by both frontend and backend. If front-end and back-end communication is not required, leave it blank.\n- Shared Knowledge: <class \'str\'>  # Detail any shared knowledge, like common utility functions or configuration variables.\n- Anything UNCLEAR: <class \'str\'>  # Mention any unresolved questions or clarifications needed from the paper or project scope.\n\n## Constraint\nFormat: output wrapped inside [CONTENT][/CONTENT] like the format example, nothing else.\n\n## Action\nFollow the node instructions above, generate your output accordingly, and ensure it follows the given format example.'}]
    config_msg = [{'role': 'user', 'content': 'You write elegant, modular, and maintainable code. Adhere to Google-style guidelines.\n\nBased on the paper, plan, design specified previously, follow the "Format Example" and generate the code. \nExtract the training details from the above paper (e.g., learning rate, batch size, epochs, etc.), follow the "Format example" and generate the code. \nDO NOT FABRICATE DETAILS — only use what the paper provides.\n\nYou must write `config.yaml`.\n\nATTENTION: Use \'##\' to SPLIT SECTIONS, not \'#\'. Your output format must follow the example below exactly.\n\n-----\n\n# Format Example\n## Code: config.yaml\n```yaml\n## config.yaml\ntraining:\n  learning_rate: ...\n  batch_size: ...\n  epochs: ...\n...\n```\n\n-----\n\n## Code: config.yaml\n'}]
    return [plan_msg, file_list_msg, task_list_msg, config_msg]

def analysis_messages(paper_content: str, paper_format: str, context: list[str], config_yaml: str, todo_file_name: str, todo_file_desc: str) -> list[dict[str, str]]:
    """Build the original per-file analysis instructions."""
    analysis_msg = [{'role': 'system', 'content': f'You are an expert researcher, strategic analyzer and software engineer with a deep understanding of experimental design and reproducibility in scientific research.\nYou will receive a research paper in {paper_format} format, an overview of the plan, a design in JSON format consisting of "Implementation approach", "File list", "Data structures and interfaces", and "Program call flow", followed by a task in JSON format that includes "Required packages", "Required other language third-party packages", "Logic Analysis", and "Task list", along with a configuration file named "config.yaml". \n\nYour task is to conduct a comprehensive logic analysis to accurately reproduce the experiments and methodologies described in the research paper. \nThis analysis must align precisely with the paper’s methodology, experimental setup, and evaluation criteria.\n\n1. Align with the Paper: Your analysis must strictly follow the methods, datasets, model configurations, hyperparameters, and experimental setups described in the paper.\n2. Be Clear and Structured: Present your analysis in a logical, well-organized, and actionable format that is easy to follow and implement.\n3. Prioritize Efficiency: Optimize the analysis for clarity and practical implementation while ensuring fidelity to the original experiments.\n4. Follow design: YOU MUST FOLLOW "Data structures and interfaces". DONT CHANGE ANY DESIGN. Do not use public member functions that do not exist in your design.\n5. REFER TO CONFIGURATION: Always reference settings from the config.yaml file. Do not invent or assume any values—only use configurations explicitly provided.\n     \n'}]
    draft_desc = f"Write the logic analysis in '{todo_file_name}', which is intended for '{todo_file_desc}'."
    if len(todo_file_desc.strip()) == 0:
        draft_desc = f"Write the logic analysis in '{todo_file_name}'."
    write_msg = [{'role': 'user', 'content': f"## Paper\n{paper_content}\n\n-----\n\n## Overview of the plan\n{context[0]}\n\n-----\n\n## Design\n{context[1]}\n\n-----\n\n## Task\n{context[2]}\n\n-----\n\n## Configuration file\n```yaml\n{config_yaml}\n```\n-----\n\n## Instruction\nConduct a Logic Analysis to assist in writing the code, based on the paper, the plan, the design, the task and the previously specified configuration file (config.yaml). \nYou DON'T need to provide the actual code yet; focus on a thorough, clear analysis.\n\n{draft_desc}\n\n-----\n\n## Logic Analysis: {todo_file_name}"}]
    return analysis_msg + write_msg

def coding_messages(paper_content: str, paper_format: str, context: list[str], config_yaml: str, todo_file_name: str, detailed_logic_analysis: str, done_files: dict[str, str]) -> list[dict[str, str]]:
    """Build the original code instructions with previously generated files."""
    code_msg = [{'role': 'system', 'content': f"""You are an expert researcher and software engineer with a deep understanding of experimental design and reproducibility in scientific research.\nYou will receive a research paper in {paper_format} format, an overview of the plan, a Design in JSON format consisting of "Implementation approach", "File list", "Data structures and interfaces", and "Program call flow", followed by a Task in JSON format that includes "Required packages", "Required other language third-party packages", "Logic Analysis", and "Task list", along with a configuration file named "config.yaml". \nYour task is to write code to reproduce the experiments and methodologies described in the paper. \n\nThe code you write must be elegant, modular, and maintainable, adhering to Google-style guidelines. \nThe code must strictly align with the paper's methodology, experimental setup, and evaluation metrics. \nWrite code with triple quoto."""}]
    done_file_lst = list(done_files)
    code_files = ''
    for done_file in done_file_lst:
        if done_file.endswith('.yaml'):
            continue
        code_files += f'\n```python\n{done_files[done_file]}\n```\n\n'
    write_msg = [{'role': 'user', 'content': f'''# Context\n## Paper\n{paper_content}\n\n-----\n\n## Overview of the plan\n{context[0]}\n\n-----\n\n## Design\n{context[1]}\n\n-----\n\n## Task\n{context[2]}\n\n-----\n\n## Configuration file\n```yaml\n{config_yaml}\n```\n-----\n\n## Code Files\n{code_files}\n\n-----\n\n# Format example\n## Code: {todo_file_name}\n```python\n## {todo_file_name}\n...\n```\n\n-----\n\n# Instruction\nBased on the paper, plan, design, task and configuration file(config.yaml) specified previously, follow "Format example", write the code. \n\nWe have {done_file_lst}.\nNext, you must write only the "{todo_file_name}".\n1. Only One file: do your best to implement THIS ONLY ONE FILE.\n2. COMPLETE CODE: Your code will be part of the entire project, so please implement complete, reliable, reusable code snippets.\n3. Set default value: If there is any setting, ALWAYS SET A DEFAULT VALUE, ALWAYS USE STRONG TYPE AND EXPLICIT VARIABLE. AVOID circular import.\n4. Follow design: YOU MUST FOLLOW "Data structures and interfaces". DONT CHANGE ANY DESIGN. Do not use public member functions that do not exist in your design.\n5. CAREFULLY CHECK THAT YOU DONT MISS ANY NECESSARY CLASS/FUNCTION IN THIS FILE.\n6. Before using a external variable/module, make sure you import it first.\n7. Write out EVERY CODE DETAIL, DON'T LEAVE TODO.\n8. REFER TO CONFIGURATION: you must use configuration from "config.yaml". DO NOT FABRICATE any configuration values.\n\n{detailed_logic_analysis}\n\n## Code: {todo_file_name}'''}]
    return code_msg + write_msg

def reproduction_messages(config_yaml: str, done_files: dict[str, str]) -> list[dict[str, str]]:
    """Build the original reproduction script instructions."""
    code_msg = [{'role': 'system', 'content': f'You are an expert researcher and software engineer with a deep understanding of experimental design and reproducibility in scientific research.\nYou will receive configuration file named "config.yaml", and implmented code repository. \nYour task is to write a Bash script that can run the given repository from scratch. The script should create and activate the required environment, install all dependencies, and include the commands needed to execute the main file or entry point. Make sure the script is self-contained and can be executed without any manual setup.\n     \nWrite code with triple quoto.'}]
    todo_file_name = 'reproduce.sh'
    done_file_lst = list(done_files)
    code_files = ''
    for done_file in done_file_lst:
        if done_file.endswith('.yaml'):
            continue
        code_files += f'\n```python\n{done_files[done_file]}\n```\n\n'
    write_msg = [{'role': 'user', 'content': f'# Context\n\n## Configuration file\n```yaml\n{config_yaml}\n```\n-----\n\n## Code Files\n{code_files}\n\n-----\n\n# Format example\n## Code: {todo_file_name}\n```python\n## {todo_file_name}\n...\n```\n\n-----\n\n# Instruction\nBased on the code files, follow "Format example", write the code. \n\nWe have {done_file_lst}.\nNext, you must write only the "{todo_file_name}".\n\n## Code: {todo_file_name}'}]
    return code_msg + write_msg

def debugging_messages(code_text: str, error_text: str) -> list[dict[str, str]]:
    """Build the original error-driven debugging instructions."""
    codes = code_text
    msg = [{'role': 'system', 'content': 'You are a highly capable code assistant specializing in debugging real-world code repositories. You will be provided with:\n(1) a code repository (in part or in full), and\n(2) one or more execution error messages generated during the execution of the repository.\n\nYour objective is to debug the code so that it executes successfully.\nThis may involve identifying the root causes of the errors, modifying faulty logic or syntax, handling missing dependencies, or making other appropriate corrections.\n\nGuidelines:\n- Provide the exact lines or file changes needed to resolve the issue.\n- When necessary, suggest best practices or improvements to prevent similar issues.\n- Show only the modified lines using a unified diff format:\n\n<<<<<<< SEARCH  \n    original line  \n=======  \n    corrected line  \n>>>>>>> REPLACE  \n\n- If multiple fixes are needed, provide them sequentially with clear separation.\n- If external dependencies or environment setups are required (for example, packages, versions, file paths), specify them explicitly.\n\nConstraints:\n- Do not make speculative edits without justification.\n- Do not assume access to an internet connection for installation or retrieval unless explicitly stated.\n- Prioritize minimal and effective fixes that preserve the original intent of the code.\n- Maintain the coding style and structure used in the original repository unless refactoring is necessary for correctness.\n'}, {'role': 'user', 'content': f'\n### Code Repository\n{codes}\n\n--\n\n### Execution Error Messages\n{error_text}\n\n--\n\n## Instruction\nNow, you need to debug the above code so that it runs without errors. Identify the cause of the execution error and modify the code appropriately. Your output must follow the exact format as shown in the example below.\n\n--\n\n## Format Example\nFilename: train.py\n<<<<<<< SEARCH\nresult = model.predict(input_data)\n=======\nresult = model(input_data)\n>>>>>>> REPLACE\n\n--\n\n## Answer\n'}]
    return msg

def refinement_messages(config_yaml: str) -> list[dict[str, str]]:
    """Build the original configuration name-detection instructions."""
    codes = f'```yaml\n## File name: config.yaml\n{config_yaml}\n```\n\n'
    messages = [{'role': 'system', 'content': 'You are an expert code assistant. Your task is to identify the model name and dataset names in the given configuration file. Return them as a list of strings in the exact format shown in the example below. Do not include any other text or commentary.'}, {'role': 'user', 'content': f'\n### Configuration file\n{codes}\n\n---\n\n## Instruction\nDetect the model name and dataset names in the configuration file so that they can be downloaded successfully from Hugging Face. Your output must strictly follow the format below.\n\n---\n\n## Format Example\n["Llama-3", "TriviaQA"]\n\n---\n\n## Answer\n'}]
    return messages
